}

package com.sessionscribe;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("sessionscribe")
public interface SessionScribeConfig extends Config
{
	@ConfigItem(
		keyName = "showSkillBreakdown",
		name = "Show skill breakdown",
		description = "Show the collapsible per-skill XP breakdown in the panel.",
		position = 1
	)
	default boolean showSkillBreakdown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "relogGapMinutes",
		name = "Relog continuation (min)",
		description = "If you log back into the same account within this many minutes, the session continues instead of starting a new one.",
		position = 4
	)
	default int relogGapMinutes()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "roundValues",
		name = "Round large values",
		description = "Abbreviate large XP and GP values (e.g. 1.2M) instead of showing full numbers.",
		position = 3
	)
	default boolean roundValues()
	{
		return false;
	}
}

package com.sessionscribe;

import java.util.EnumMap;
import java.util.Map;
import net.runelite.api.Skill;

/** A record of one completed session (stable after construction). Per-item loot is not stored here. */
final class SessionRecord
{
	long startMs;
	long endMs;
	long durationMs;
	Map<Skill, Integer> xpBySkill = new EnumMap<>(Skill.class);
	long lootValue;
	int kills;

	// Gson uses field injection on deserialize; this constructor is for our code.
	SessionRecord(long startMs, long endMs, long durationMs, Map<Skill, Integer> xpBySkill, long lootValue, int kills)
	{
		this.startMs = startMs;
		this.endMs = endMs;
		this.durationMs = durationMs;
		this.xpBySkill = (xpBySkill == null || xpBySkill.isEmpty()) ? new EnumMap<>(Skill.class) : new EnumMap<>(xpBySkill);
		this.lootValue = lootValue;
		this.kills = kills;
	}
}

package com.sessionscribe;

import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Skill;

/** A session mirrored to disk while in progress, so a crash does not lose it. */
final class PendingSession
{
	long startMs;
	long durationMs;
	Map<Skill, Integer> xpBySkill = new EnumMap<>(Skill.class);
	long lootValue;
	int kills;
	Map<Integer, Integer> lootTally = new HashMap<>();
	long logoutMs; // wall-clock time of the last logout event (for the relog-gap check, not session end)
}

package com.sessionscribe;

import java.util.concurrent.TimeUnit;

enum Window
{
	CURRENT("Current session"),
	DAY("Last 24 hours", TimeUnit.DAYS.toMillis(1)),
	WEEK("Last 7 days", TimeUnit.DAYS.toMillis(7)),
	ALL_TIME("All time");

	private final String label;
	private final long spanMillis;

	Window(String label)
	{
		this(label, -1L);
	}

	Window(String label, long spanMillis)
	{
		this.label = label;
		this.spanMillis = spanMillis;
	}

	String label()
	{
		return label;
	}

	boolean isRolling()
	{
		return spanMillis > 0;
	}

	long spanMillis()
	{
		return spanMillis;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.sessionscribe;

/** Number formatting shared by the live panel and the report card. */
final class Values
{
	private Values()
	{
	}

	/** Plain grouped count, e.g. 18,500. Used for item quantities (never abbreviated). */
	static String count(long value)
	{
		return String.format("%,d", value);
	}

	/** Formats an XP/GP value: grouped digits, or abbreviated (1.2M / 345K) when {@code rounded}. */
	static String format(long value, boolean rounded)
	{
		if (!rounded)
		{
			return String.format("%,d", value);
		}
		final long abs = Math.abs(value);
		if (abs >= 1_000_000_000L)
		{
			return trim(value / 1_000_000_000.0) + "B";
		}
		if (abs >= 1_000_000L)
		{
			return trim(value / 1_000_000.0) + "M";
		}
		if (abs >= 1_000L)
		{
			return trim(value / 1_000.0) + "K";
		}
		return Long.toString(value);
	}

	private static String trim(double value)
	{
		final String formatted = String.format("%.1f", value);
		return formatted.endsWith(".0") ? formatted.substring(0, formatted.length() - 2) : formatted;
	}
}

package com.sessionscribe;

import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

/**
 * In-memory tally of everything gained during the current play session: XP per skill, loot
 * quantities, kills, and elapsed time. Nothing is persisted while tracking.
 *
 * Threading: every mutator must run on the client thread. Game events (StatChanged, loot,
 * GameStateChanged) are already dispatched there; reset calls are wrapped in
 * {@code ClientThread#invoke} by the plugin.
 *
 * Honest limitation: a kill is only counted when it produces an NpcLootReceived event.
 * Drop-less kills (nothing dropped) are NOT counted.
 */
@Singleton
public class SessionTracker
{
	/** Defensive cap on the number of distinct loot item ids held in memory. */
	static final int MAX_LOOT_ENTRIES = 1000;

	@Inject
	private ItemManager itemManager;

	private long sessionStart = System.currentTimeMillis();

	private final Map<Skill, Integer> baseline = new EnumMap<>(Skill.class);
	private final Map<Skill, Integer> gained = new EnumMap<>(Skill.class);
	private final Map<Integer, Integer> loot = new HashMap<>();
	private int kills;

	/** Clear all counters and start a fresh session. */
	public void reset()
	{
		sessionStart = System.currentTimeMillis();
		baseline.clear();
		gained.clear();
		loot.clear();
		kills = 0;
		// Baselines are (re)established lazily by the first StatChanged per skill after a reset.
	}

	public void recordXp(Skill skill, int currentXp)
	{
		Integer base = baseline.get(skill);
		if (base == null || currentXp < base)
		{
			// First reading after a reset, or XP appears lower than the baseline (stats reloaded on
			// login/world-hop): (re)baseline here so a session never shows a negative or inflated gain.
			setBaseline(skill, currentXp);
			return;
		}
		gained.put(skill, currentXp - base);
	}

	public void recordKill()
	{
		kills++;
	}

	public void addLoot(int itemId, int quantity)
	{
		Integer existing = loot.get(itemId);
		if (existing == null && loot.size() >= MAX_LOOT_ENTRIES)
		{
			return;
		}
		loot.put(itemId, (existing == null ? 0 : existing) + quantity);
	}

	void setBaseline(Skill skill, int xp)
	{
		baseline.put(skill, xp);
		gained.remove(skill);
	}

	public long getElapsedMillis()
	{
		return System.currentTimeMillis() - sessionStart;
	}

	public long getTotalXp()
	{
		long total = 0;
		for (int gain : gained.values())
		{
			total += gain;
		}
		return total;
	}

	public Map<Skill, Integer> getXpBySkill()
	{
		return Collections.unmodifiableMap(new EnumMap<>(gained));
	}

	public Map<Integer, Integer> getLootTally()
	{
		return Collections.unmodifiableMap(new HashMap<>(loot));
	}

	public long getTotalLootValue()
	{
		return totalLootValue(itemManager::getItemPrice);
	}

	/** Value math seam: kept separate from {@link ItemManager} so it is unit-testable. */
	long totalLootValue(IntUnaryOperator priceFn)
	{
		long total = 0;
		for (Map.Entry<Integer, Integer> entry : loot.entrySet())
		{
			total += (long) priceFn.applyAsInt(entry.getKey()) * entry.getValue();
		}
		return total;
	}

	public int getKills()
	{
		return kills;
	}
}

package com.sessionscribe;

