package com.sessionscribe;

import com.google.inject.Provides;
import java.awt.Toolkit;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.RuneLite;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Session Scribe",
	description = "Unified end-of-session recap: XP, loot value, kills, and playtime.",
	tags = {"session", "summary", "xp", "loot", "stats"}
)
public class SessionScribePlugin extends Plugin
{
	private static final long REFRESH_THROTTLE_MS = 600;
	private static final int MAX_LOOT_ROWS = 10;

	@Inject
	private SessionTracker tracker;

	@Inject
	private SessionStore store;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private SessionScribeConfig config;

	private SessionScribePanel panel;
	private NavigationButton navButton;
	private long lastRefresh;
	private String currentAccount;
	private long pendingLogoutMs;
	private String selectedAccount;
	private Window selectedWindow = Window.CURRENT;
	private boolean continuedAfterRelog;

	@Override
	protected void startUp()
	{
		panel = new SessionScribePanel(config, this::requestNewSession, this::requestCopyImage,
			this::requestSaveImage, this::requestClearHistory, this::onSelectionChanged);

		final BufferedImage icon = ImageUtil.loadImageResource(SessionScribePlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Session Scribe")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		executor.execute(() ->
		{
			store.load();
			store.finalizeLeftoverPending(itemManager::getItemPrice);
			clientThread.invoke(() ->
			{
				tracker.reset();
				pushUpdate();
			});
		});
	}

	@Override
	protected void shutDown()
	{
		finalizeCurrent();
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		tracker.recordXp(event.getSkill(), event.getXp());
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		// A kill is inferred from its loot drop; drop-less kills go uncounted (see SessionTracker).
		tracker.recordKill();
		for (ItemStack item : event.getItems())
		{
			tracker.addLoot(item.getId(), item.getQuantity());
		}
	}

	@Subscribe
	public void onPlayerLootReceived(PlayerLootReceived event)
	{
		for (ItemStack item : event.getItems())
		{
			tracker.addLoot(item.getId(), item.getQuantity());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				handleLogin();
				break;
			case LOGIN_SCREEN:
				handleLogout();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() == GameState.LOGGED_IN && currentAccount == null)
		{
			handleLogin();
		}
		final long now = System.currentTimeMillis();
		if (now - lastRefresh < REFRESH_THROTTLE_MS)
		{
			return;
		}
		lastRefresh = now;
		pushUpdate();
	}

	private void requestNewSession()
	{
		clientThread.invoke(() ->
		{
			final boolean archived = currentAccount != null && hasCurrentSessionData();
			finalizeCurrent();
			tracker.reset();
			continuedAfterRelog = false;
			pushUpdate();
			SwingUtilities.invokeLater(() -> panel.showExportStatus(archived ? "Session archived" : "New session started"));
		});
	}

	private void handleLogin()
	{
		final Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return;
		}
		final String account = local.getName();

		if (currentAccount == null)
		{
			currentAccount = account;
			if (selectedAccount == null)
			{
				selectedAccount = account;
			}
			pendingLogoutMs = 0;
			pushUpdate();
			return;
		}

		if (account.equals(currentAccount) && SessionStore.withinGap(pendingLogoutMs, System.currentTimeMillis(),
			(long) config.relogGapMinutes() * 60_000))
		{
			pendingLogoutMs = 0;
			continuedAfterRelog = true;
			pushUpdate();
			return;
		}

		finalizeCurrent();
		currentAccount = account;
		selectedAccount = account;
		pendingLogoutMs = 0;
		continuedAfterRelog = false;
		tracker.reset();
		pushUpdate();
	}

	private void handleLogout()
	{
		if (currentAccount == null)
		{
			return;
		}
		pendingLogoutMs = System.currentTimeMillis();
		final SessionRecord record = snapshotRecord();
		final Map<Integer, Integer> tally = tracker.getLootTally();
		final String account = currentAccount;
		final long logoutMs = pendingLogoutMs;
		executor.execute(() -> store.savePending(account, record, tally, logoutMs));
	}

	private SessionRecord snapshotRecord()
	{
		final long now = System.currentTimeMillis();
		final long duration = tracker.getElapsedMillis();
		return new SessionRecord(now - duration, now, duration,
			tracker.getXpBySkill(), tracker.getTotalLootValue(), tracker.getKills());
	}

	private void finalizeCurrent()
	{
		if (currentAccount == null)
		{
			return;
		}
		final boolean empty = tracker.getTotalXp() == 0 && tracker.getKills() == 0
			&& tracker.getLootTally().isEmpty();
		if (empty)
		{
			store.clearPending(currentAccount);
			return;
		}
		final SessionRecord record = snapshotRecord();
		final Map<Integer, Integer> tally = tracker.getLootTally();
		final String account = currentAccount;
		executor.execute(() ->
		{
			store.finalizeSession(account, record, tally, itemManager::getItemPrice);
			store.clearPending(account);
			store.save();
		});
	}

	private void requestCopyImage()
	{
		// Build the snapshot on the client thread, then place the rendered image on the clipboard (EDT).
		clientThread.invoke(() ->
		{
			final BufferedImage image = SessionReportCard.render(buildSnapshot(), config.roundValues(), selectedSubtitle());
			SwingUtilities.invokeLater(() ->
			{
				Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageTransferable(image), null);
				panel.showExportStatus("Copied recap to clipboard");
			});
		});
	}

	private void requestSaveImage()
	{
		clientThread.invoke(() ->
		{
			final BufferedImage image = SessionReportCard.render(buildSnapshot(), config.roundValues(), selectedSubtitle());
			String message;
			try
			{
				final File saved = SessionReportCard.saveTo(image, new File(RuneLite.RUNELITE_DIR, "session-scribe"));
				message = "Saved " + saved.getName();
			}
			catch (IOException e)
			{
				log.warn("Failed to save session recap", e);
				message = "Save failed (see logs)";
			}
			final String result = message;
			SwingUtilities.invokeLater(() -> panel.showExportStatus(result));
		});
	}

	private void requestClearHistory()
	{
		final String account = selectedAccount != null ? selectedAccount : currentAccount;
		final String target = account == null ? "all local history" : "history for " + account;
		final int choice = JOptionPane.showConfirmDialog(panel,
			"Clear " + target + "?",
			"Clear history",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE);
		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}
		clientThread.invoke(() ->
		{
			if (account != null)
			{
				store.clearAccount(account);
				selectedAccount = currentAccount;
			}
			else
			{
				store.clearAll();
			}
			executor.execute(store::save);
			pushUpdate();
			SwingUtilities.invokeLater(() -> panel.showExportStatus("History cleared"));
		});
	}

	/** Builds an immutable snapshot on the client thread, then hands it to the EDT to render. */
	private void pushUpdate()
	{
		if (panel == null)
		{
			return;
		}
		final String account = selectedAccount != null ? selectedAccount : currentAccount;
		final Window window = selectedWindow;
		final SessionRecord live = shouldIncludeLive(account) ? snapshotRecord() : null;
		final Map<Integer, Integer> liveTally = live != null ? tracker.getLootTally() : null;
		final Aggregate aggregate = store.aggregate(account, window, System.currentTimeMillis(),
			live, liveTally, itemManager::getItemPrice);
		final boolean itemized = window == Window.CURRENT || window == Window.ALL_TIME;
		final SessionScribePanel.Snapshot snapshot = toSnapshot(aggregate, itemized, contextText(window, live != null));
		final List<String> accountList = new ArrayList<>(store.accounts());
		if (currentAccount != null && !accountList.contains(currentAccount))
		{
			accountList.add(currentAccount);
		}
		final String selected = account;
		SwingUtilities.invokeLater(() ->
		{
			panel.setAccounts(accountList, selected);
			panel.render(snapshot);
		});
	}

	private SessionScribePanel.Snapshot buildSnapshot()
	{
		final String account = selectedAccount != null ? selectedAccount : currentAccount;
		final Window window = selectedWindow;
		final SessionRecord live = shouldIncludeLive(account) ? snapshotRecord() : null;
		final Map<Integer, Integer> liveTally = live != null ? tracker.getLootTally() : null;
		final Aggregate aggregate = store.aggregate(account, window, System.currentTimeMillis(),
			live, liveTally, itemManager::getItemPrice);
		return toSnapshot(aggregate, window == Window.CURRENT || window == Window.ALL_TIME,
			contextText(window, live != null));
	}

	private boolean shouldIncludeLive(String account)
	{
		return account == null || account.equals(currentAccount);
	}

	private String selectedSubtitle()
	{
		final String account = selectedAccount != null ? selectedAccount : currentAccount;
		return (account == null ? "Unknown" : account) + " - " + selectedWindow.label();
	}

	private SessionScribePanel.Snapshot toSnapshot(Aggregate aggregate, boolean itemized, String contextText)
	{
		final List<SessionScribePanel.SkillRow> skillRows = new ArrayList<>();
		for (Map.Entry<Skill, Integer> entry : aggregate.xpBySkill.entrySet())
		{
			if (entry.getValue() > 0)
			{
				skillRows.add(new SessionScribePanel.SkillRow(entry.getKey(), entry.getValue()));
			}
		}
		skillRows.sort((a, b) -> Integer.compare(b.gainedXp(), a.gainedXp()));

		final List<SessionScribePanel.LootRow> lootRows = new ArrayList<>();
		if (itemized && aggregate.lootTally != null)
		{
			for (Map.Entry<Integer, Integer> entry : aggregate.lootTally.entrySet())
			{
				final int itemId = entry.getKey();
				final int quantity = entry.getValue();
				final long value = (long) itemManager.getItemPrice(itemId) * quantity;
				final String name = itemManager.getItemComposition(itemId).getName();
				final AsyncBufferedImage image = itemManager.getImage(itemId, quantity, quantity > 1);
				lootRows.add(new SessionScribePanel.LootRow(name, quantity, value, image));
			}
			lootRows.sort((a, b) -> Long.compare(b.value(), a.value()));
		}

		final List<SessionScribePanel.LootRow> topLoot = lootRows.size() > MAX_LOOT_ROWS
			? new ArrayList<>(lootRows.subList(0, MAX_LOOT_ROWS))
			: lootRows;

		return new SessionScribePanel.Snapshot(aggregate.durationMs, aggregate.totalXp(),
			aggregate.lootValue, aggregate.kills, skillRows, topLoot, contextText, itemized);
	}

	private boolean hasCurrentSessionData()
	{
		return tracker.getTotalXp() > 0 || tracker.getKills() > 0 || !tracker.getLootTally().isEmpty();
	}

	private String contextText(Window window, boolean includesLive)
	{
		if (window == Window.CURRENT)
		{
			if (continuedAfterRelog)
			{
				return "Continuing after relog";
			}
			return "Started " + formatAgo(tracker.getElapsedMillis()) + " ago";
		}
		return includesLive ? "Includes current session" : "Completed sessions only";
	}

	private static String formatAgo(long millis)
	{
		final long totalMinutes = Math.max(0, millis / 60_000);
		final long hours = totalMinutes / 60;
		final long minutes = totalMinutes % 60;
		if (hours > 0)
		{
			return hours + "h " + minutes + "m";
		}
		return minutes + "m";
	}

	void onSelectionChanged(String account, Window window)
	{
		selectedAccount = account;
		selectedWindow = window;
		clientThread.invoke(this::pushUpdate);
	}

	@Provides
	SessionScribeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SessionScribeConfig.class);
	}
}

package com.sessionscribe;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import java.util.function.BiConsumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Live recap panel. Rendered entirely on the EDT from immutable {@link Snapshot}s that the
 * plugin builds on the client thread, so no client-thread work happens inside Swing callbacks.
 */
public class SessionScribePanel extends PluginPanel
{
	private final JLabel elapsedValue = statValue();
	private final JLabel xpValue = statValue();
	private final JLabel gpValue = statValue();
	private final JLabel killsValue = statValue();

	private final JComboBox<String> accountSelector = new JComboBox<>();
	private final JComboBox<Window> windowSelector = new JComboBox<>(Window.values());
	private final JLabel sessionContext = new JLabel(" ");
	private final JButton skillToggle = new JButton();
	private final JPanel skillBody = new JPanel();
	private final JPanel lootBody = new JPanel();
	private final JLabel status = new JLabel(" ");

	private final SessionScribeConfig config;
	private final BiConsumer<String, Window> onSelectionChanged;
	private boolean skillsExpanded;
	private boolean updatingAccounts;

	public SessionScribePanel(SessionScribeConfig config, Runnable onNewSession, Runnable onCopyImage,
		Runnable onSaveImage, Runnable onClearHistory, BiConsumer<String, Window> onSelectionChanged)
	{
		this.config = config;
		this.onSelectionChanged = onSelectionChanged;
		setLayout(new BorderLayout());

		final JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));

		content.add(sectionLabel("Session Scribe"));

		final JPanel selectors = new JPanel(new GridLayout(0, 1, 0, 4));
		accountSelector.addActionListener(e -> fireSelection());
		windowSelector.addActionListener(e -> fireSelection());
		selectors.add(accountSelector);
		selectors.add(windowSelector);
		content.add(selectors);

		sessionContext.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		sessionContext.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		content.add(sessionContext);

		final JPanel stats = new JPanel(new GridLayout(0, 2, 6, 4));
		stats.setBorder(BorderFactory.createEmptyBorder(6, 0, 6, 0));
		stats.add(new JLabel("Time"));
		stats.add(elapsedValue);
		stats.add(new JLabel("XP gained"));
		stats.add(xpValue);
		stats.add(new JLabel("Loot value"));
		stats.add(gpValue);
		stats.add(new JLabel("Kills"));
		stats.add(killsValue);
		content.add(stats);

		skillToggle.setFocusPainted(false);
		skillToggle.addActionListener(e -> toggleSkills());
		content.add(skillToggle);

		skillBody.setLayout(new BoxLayout(skillBody, BoxLayout.Y_AXIS));
		skillBody.setBorder(BorderFactory.createEmptyBorder(2, 4, 6, 0));
		skillBody.setVisible(false);
		content.add(skillBody);

		content.add(sectionLabel("Top loot"));
		lootBody.setLayout(new BoxLayout(lootBody, BoxLayout.Y_AXIS));
		lootBody.setBorder(BorderFactory.createEmptyBorder(2, 0, 6, 0));
		content.add(lootBody);

		final JPanel actions = new JPanel(new GridLayout(0, 1, 0, 4));
		actions.setBorder(BorderFactory.createEmptyBorder(8, 0, 4, 0));
		actions.add(actionButton("New Session", onNewSession));
		actions.add(actionButton("Copy image", onCopyImage));
		actions.add(actionButton("Save image", onSaveImage));
		actions.add(actionButton("Clear history", onClearHistory));
		content.add(actions);

		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setAlignmentX(Component.LEFT_ALIGNMENT);
		content.add(status);

		updateSkillToggleText(0);
		add(content, BorderLayout.NORTH);
	}

	/** Render a snapshot. Must be called on the EDT. */
	public void render(Snapshot snapshot)
	{
		final boolean rounded = config.roundValues();
		elapsedValue.setText(formatElapsed(snapshot.elapsedMillis));
		xpValue.setText(Values.format(snapshot.totalXp, rounded));
		gpValue.setText(Values.format(snapshot.totalLootValue, rounded) + " gp");
		killsValue.setText(Integer.toString(snapshot.kills));
		sessionContext.setText(snapshot.contextText);

		final boolean showSkills = config.showSkillBreakdown();
		skillToggle.setVisible(showSkills);
		if (showSkills)
		{
			updateSkillToggleText(snapshot.skillRows.size());
			skillBody.removeAll();
			if (snapshot.skillRows.isEmpty())
			{
				skillBody.add(mutedLabel("No XP yet"));
			}
			else
			{
				for (SkillRow row : snapshot.skillRows)
				{
					skillBody.add(textRow(formatSkillName(row.skill), "+" + Values.format(row.gained, rounded)));
				}
			}
			skillBody.setVisible(skillsExpanded);
		}
		else
		{
			skillBody.setVisible(false);
		}

		lootBody.removeAll();
		if (!snapshot.itemizedLoot)
		{
			lootBody.add(mutedLabel("Top loot unavailable for this window"));
		}
		else if (snapshot.lootRows.isEmpty())
		{
			lootBody.add(mutedLabel("No loot yet"));
		}
		else
		{
			for (LootRow row : snapshot.lootRows)
			{
				lootBody.add(lootRow(row));
			}
		}

		revalidate();
		repaint();
	}

	/** Refresh the account dropdown contents without firing the listener. */
	public void setAccounts(List<String> accounts, String selected)
	{
		updatingAccounts = true;
		try
		{
			final DefaultComboBoxModel<String> model = new DefaultComboBoxModel<>();
			if (accounts.isEmpty())
			{
				model.addElement("Log in to track account");
				accountSelector.setEnabled(false);
			}
			else
			{
				accountSelector.setEnabled(true);
				for (String account : accounts)
				{
					model.addElement(account);
				}
			}
			accountSelector.setModel(model);
			if (selected != null)
			{
				accountSelector.setSelectedItem(selected);
			}
		}
		finally
		{
			updatingAccounts = false;
		}
	}

	/** Show a one-line result after an export. Must be called on the EDT. */
	public void showExportStatus(String message)
	{
		status.setText(message);
	}

	private void fireSelection()
	{
		if (updatingAccounts || !accountSelector.isEnabled())
		{
			return;
		}
		final Object account = accountSelector.getSelectedItem();
		final Object window = windowSelector.getSelectedItem();
		if (window != null)
		{
			onSelectionChanged.accept(account == null ? null : account.toString(), (Window) window);
		}
	}

	private void toggleSkills()
	{
		skillsExpanded = !skillsExpanded;
		skillBody.setVisible(skillsExpanded);
		updateSkillToggleText(skillBody.getComponentCount());
		revalidate();
		repaint();
	}

	private void updateSkillToggleText(int count)
	{
		skillToggle.setText((skillsExpanded ? "▾" : "▸") + " Skill XP (" + count + ")");
	}

	private JPanel lootRow(LootRow row)
	{
		final JPanel panel = new JPanel(new BorderLayout(6, 0));
		panel.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));

		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		row.image.addTo(icon);
		panel.add(icon, BorderLayout.WEST);

		final String name = row.quantity > 1 ? row.name + " x " + Values.count(row.quantity) : row.name;
		panel.add(new JLabel(name), BorderLayout.CENTER);

		final JLabel value = new JLabel(Values.format(row.value, config.roundValues()) + " gp");
		value.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		panel.add(value, BorderLayout.EAST);
		return panel;
	}

	private static JButton actionButton(String text, Runnable action)
	{
		final JButton button = new JButton(text);
		button.setFocusPainted(false);
		button.addActionListener(e -> action.run());
		return button;
	}

	private static JPanel textRow(String left, String right)
	{
		final JPanel panel = new JPanel(new BorderLayout());
		panel.add(new JLabel(left), BorderLayout.WEST);
		final JLabel rightLabel = new JLabel(right);
		rightLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		panel.add(rightLabel, BorderLayout.EAST);
		return panel;
	}

	private static JLabel statValue()
	{
		return new JLabel("-", SwingConstants.RIGHT);
	}

	private static JLabel sectionLabel(String text)
	{
		final JLabel label = new JLabel(text);
		label.setFont(label.getFont().deriveFont(label.getFont().getStyle() | java.awt.Font.BOLD));
		label.setBorder(BorderFactory.createEmptyBorder(4, 0, 2, 0));
		return label;
	}

	private static JLabel mutedLabel(String text)
	{
		final JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		return label;
	}

	private static String formatSkillName(Skill skill)
	{
		final String name = skill.name();
		return name.charAt(0) + name.substring(1).toLowerCase();
	}

	private static String formatElapsed(long millis)
	{
		final long totalSeconds = millis / 1000;
		final long hours = totalSeconds / 3600;
		final long minutes = (totalSeconds % 3600) / 60;
		final long seconds = totalSeconds % 60;
		return hours > 0
			? String.format("%d:%02d", hours, minutes)
			: String.format("%02d:%02d", minutes, seconds);
	}

	/** Immutable view built on the client thread and handed to {@link #render(Snapshot)}. */
	public static final class Snapshot
	{
		private final long elapsedMillis;
		private final long totalXp;
		private final long totalLootValue;
		private final int kills;
		private final List<SkillRow> skillRows;
		private final List<LootRow> lootRows;
		private final String contextText;
		private final boolean itemizedLoot;

		public Snapshot(long elapsedMillis, long totalXp, long totalLootValue, int kills,
			List<SkillRow> skillRows, List<LootRow> lootRows)
		{
			this(elapsedMillis, totalXp, totalLootValue, kills, skillRows, lootRows, " ", true);
		}

		public Snapshot(long elapsedMillis, long totalXp, long totalLootValue, int kills,
			List<SkillRow> skillRows, List<LootRow> lootRows, String contextText, boolean itemizedLoot)
		{
			this.elapsedMillis = elapsedMillis;
			this.totalXp = totalXp;
			this.totalLootValue = totalLootValue;
			this.kills = kills;
			this.skillRows = skillRows;
			this.lootRows = lootRows;
			this.contextText = contextText;
			this.itemizedLoot = itemizedLoot;
		}

		public long elapsedMillis()
		{
			return elapsedMillis;
		}

		public long totalXp()
		{
			return totalXp;
		}

		public long totalLootValue()
		{
			return totalLootValue;
		}

		public int kills()
		{
			return kills;
		}

		public List<SkillRow> skillRows()
		{
			return skillRows;
		}

		public List<LootRow> lootRows()
		{
			return lootRows;
		}
	}

	public static final class SkillRow
	{
		private final Skill skill;
		private final int gained;

		public SkillRow(Skill skill, int gained)
		{
			this.skill = skill;
			this.gained = gained;
		}

		public Skill skill()
		{
			return skill;
		}

		public int gainedXp()
		{
			return gained;
		}
	}

	public static final class LootRow
	{
		private final String name;
		private final int quantity;
		private final long value;
		private final AsyncBufferedImage image;

		public LootRow(String name, int quantity, long value, AsyncBufferedImage image)
		{
			this.name = name;
			this.quantity = quantity;
			this.value = value;
			this.image = image;
		}

		public String name()
		{
			return name;
		}

		public int quantity()
		{
			return quantity;
		}

		public long value()
		{
			return value;
		}
	}
}

package com.sessionscribe;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.TimeUnit;
import java.util.function.IntUnaryOperator;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Skill;
import net.runelite.client.RuneLite;

/** In-memory per-account session history with aggregation, retention, and JSON persistence. */
@Slf4j
@Singleton
class SessionStore
{
	static final int MAX_LOOT_ENTRIES = 1000;
	static final long RETENTION_MS = TimeUnit.DAYS.toMillis(90);

	private static final int VERSION = 1;

	@Inject
	private Gson gson;

	/** Serializable top-level shape of history.json. */
	private static final class HistoryFile
	{
		int version = VERSION;
		Map<String, AccountHistory> accounts = new LinkedHashMap<>();
	}

	private Map<String, AccountHistory> accounts = new LinkedHashMap<>();

	synchronized Set<String> accounts()
	{
		return new LinkedHashMap<>(accounts).keySet();
	}

	synchronized void clearAll()
	{
		accounts.clear();
	}

	synchronized void clearAccount(String account)
	{
		accounts.remove(account);
	}

	/** Append a completed session, roll it into all-time totals, and prune old detailed rows. */
	synchronized void finalizeSession(String account, SessionRecord record, Map<Integer, Integer> lootTally,
		IntUnaryOperator priceFn)
	{
		AccountHistory history = accounts.computeIfAbsent(account, k -> new AccountHistory());
		finalizeSessionInternal(history, record, lootTally, priceFn);
	}

	synchronized void finalizeLeftoverPending(IntUnaryOperator priceFn)
	{
		for (Map.Entry<String, AccountHistory> entry : accounts.entrySet())
		{
			AccountHistory history = entry.getValue();
			PendingSession pending = history.pending;
			if (pending == null)
			{
				continue;
			}
			long end = pending.startMs + pending.durationMs;
			SessionRecord record = new SessionRecord(pending.startMs, end, pending.durationMs,
				pending.xpBySkill, pending.lootValue, pending.kills);
			finalizeSessionInternal(history, record, pending.lootTally, priceFn);
			history.pending = null;
		}
		save();
	}

	synchronized void savePending(String account, SessionRecord record, Map<Integer, Integer> lootTally, long logoutMs)
	{
		AccountHistory history = accounts.computeIfAbsent(account, k -> new AccountHistory());
		PendingSession pending = new PendingSession();
		pending.startMs = record.startMs;
		pending.durationMs = record.durationMs;
		pending.xpBySkill = record.xpBySkill;
		pending.lootValue = record.lootValue;
		pending.kills = record.kills;
		pending.lootTally = lootTally == null ? new HashMap<>() : new HashMap<>(lootTally);
		pending.logoutMs = logoutMs;
		history.pending = pending;
		save();
	}

	synchronized void clearPending(String account)
	{
		AccountHistory history = accounts.get(account);
		if (history != null)
		{
			history.pending = null;
		}
	}

	private void finalizeSessionInternal(AccountHistory history, SessionRecord record, Map<Integer, Integer> lootTally,
		IntUnaryOperator priceFn)
	{
		history.sessions.add(record);

		AllTimeStats all = history.allTime;
		if (all.sinceMs == 0)
		{
			all.sinceMs = record.startMs;
		}
		all.durationMs += record.durationMs;
		all.lootValue += record.lootValue;
		all.kills += record.kills;
		addXp(all.xpBySkill, record.xpBySkill);
		mergeLoot(all.lootTally, lootTally, priceFn);

		pruneOldSessions(history, record.endMs);
	}

	/**
	 * Aggregates stats for one (account, window). The returned {@link Aggregate} carries an itemized
	 * {@code lootTally} for CURRENT and ALL_TIME, and {@code null} for the rolling DAY / WEEK windows.
	 */
	synchronized Aggregate aggregate(String account, Window window, long now, SessionRecord current,
		Map<Integer, Integer> currentLootTally, IntUnaryOperator priceFn)
	{
		if (window == Window.CURRENT)
		{
			if (current == null)
			{
				return emptyAggregate(new HashMap<>());
			}
			return new Aggregate(current.durationMs, new EnumMap<>(current.xpBySkill),
				current.lootValue, current.kills,
				currentLootTally == null ? new HashMap<>() : new HashMap<>(currentLootTally));
		}

		AccountHistory history = accounts.get(account);
		long durationMs = 0;
		long lootValue = 0;
		int kills = 0;
		Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
		Map<Integer, Integer> tally = null;

		if (window == Window.ALL_TIME)
		{
			if (history != null)
			{
				durationMs = history.allTime.durationMs;
				lootValue = history.allTime.lootValue;
				kills = history.allTime.kills;
				addXp(xp, history.allTime.xpBySkill);
				tally = new HashMap<>(history.allTime.lootTally);
			}
			else
			{
				tally = new HashMap<>();
			}
			if (current != null)
			{
				durationMs += current.durationMs;
				lootValue += current.lootValue;
				kills += current.kills;
				addXp(xp, current.xpBySkill);
				mergeLoot(tally, currentLootTally, priceFn);
			}
			return new Aggregate(durationMs, xp, lootValue, kills, tally);
		}

		// DAY / WEEK: sum sessions whose end is within the rolling window, plus the live session.
		long cutoff = now - window.spanMillis();
		if (history != null)
		{
			for (SessionRecord record : history.sessions)
			{
				if (record.endMs >= cutoff)
				{
					durationMs += record.durationMs;
					lootValue += record.lootValue;
					kills += record.kills;
					addXp(xp, record.xpBySkill);
				}
			}
		}
		if (current != null)
		{
			durationMs += current.durationMs;
			lootValue += current.lootValue;
			kills += current.kills;
			addXp(xp, current.xpBySkill);
		}
		return new Aggregate(durationMs, xp, lootValue, kills, null);
	}

	synchronized void load()
	{
		File file = historyFile();
		if (!file.exists())
		{
			accounts = new LinkedHashMap<>();
			return;
		}
		try (Reader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8))
		{
			HistoryFile parsed = gson.fromJson(reader, HistoryFile.class);
			accounts = parsed != null && parsed.accounts != null ? parsed.accounts : new LinkedHashMap<>();
		}
		catch (Exception e)
		{
			log.warn("Could not read session history; backing up and starting fresh", e);
			backup(file);
			accounts = new LinkedHashMap<>();
		}
	}

	synchronized void save()
	{
		File file = historyFile();
		File dir = file.getParentFile();
		if (dir != null && !dir.exists() && !dir.mkdirs())
		{
			log.warn("Could not create history directory: {}", dir);
			return;
		}

		File tmp = new File(file.getParentFile(), file.getName() + ".tmp");
		try (Writer writer = Files.newBufferedWriter(tmp.toPath(), StandardCharsets.UTF_8))
		{
			HistoryFile out = new HistoryFile();
			out.accounts = accounts;
			gson.toJson(out, writer);
		}
		catch (IOException e)
		{
			log.warn("Could not write session history", e);
			return;
		}

		try
		{
			Files.move(tmp.toPath(), file.toPath(), StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException e)
		{
			log.warn("Could not replace session history file", e);
		}
	}

	static boolean withinGap(long logoutMs, long now, long gapMs)
	{
		return logoutMs > 0 && (now - logoutMs) <= gapMs;
	}

	static String toJson(Gson gson, Map<String, AccountHistory> accounts)
	{
		HistoryFile out = new HistoryFile();
		out.accounts = accounts;
		return gson.toJson(out);
	}

	static Map<String, AccountHistory> fromJson(Gson gson, String json)
	{
		try
		{
			HistoryFile parsed = gson.fromJson(json, HistoryFile.class);
			return parsed != null && parsed.accounts != null ? parsed.accounts : new LinkedHashMap<>();
		}
		catch (Exception e)
		{
			return new LinkedHashMap<>();
		}
	}

	synchronized Map<String, AccountHistory> exportForTest()
	{
		return accounts;
	}

	private static File historyFile()
	{
		return new File(RuneLite.RUNELITE_DIR, "session-scribe" + File.separator + "history.json");
	}

	private static void backup(File file)
	{
		try
		{
			Files.move(file.toPath(), new File(file.getParentFile(), file.getName() + ".corrupt").toPath(),
				StandardCopyOption.REPLACE_EXISTING);
		}
		catch (IOException ignored)
		{
			// Best effort; the next save can still replace the unreadable history file.
		}
	}

	private static Aggregate emptyAggregate(Map<Integer, Integer> tally)
	{
		return new Aggregate(0, new EnumMap<>(Skill.class), 0, 0, tally);
	}

	private static void addXp(Map<Skill, Integer> into, Map<Skill, Integer> from)
	{
		if (from == null)
		{
			return;
		}
		for (Map.Entry<Skill, Integer> e : from.entrySet())
		{
			into.merge(e.getKey(), e.getValue(), Integer::sum);
		}
	}

	private static void mergeLoot(Map<Integer, Integer> into, Map<Integer, Integer> from, IntUnaryOperator priceFn)
	{
		if (from == null)
		{
			return;
		}
		for (Map.Entry<Integer, Integer> e : from.entrySet())
		{
			into.merge(e.getKey(), e.getValue(), Integer::sum);
		}
		while (into.size() > MAX_LOOT_ENTRIES)
		{
			Integer cheapest = null;
			long cheapestValue = Long.MAX_VALUE;
			for (Map.Entry<Integer, Integer> e : into.entrySet())
			{
				long value = (long) priceFn.applyAsInt(e.getKey()) * e.getValue();
				if (value < cheapestValue)
				{
					cheapestValue = value;
					cheapest = e.getKey();
				}
			}
			into.remove(cheapest);
		}
	}

	private static void pruneOldSessions(AccountHistory history, long now)
	{
		long cutoff = now - RETENTION_MS;
		List<SessionRecord> kept = new ArrayList<>();
		for (SessionRecord record : history.sessions)
		{
			if (record.endMs >= cutoff)
			{
				kept.add(record);
			}
		}
		history.sessions = kept;
	}
}

package com.sessionscribe;

import com.sessionscribe.SessionScribePanel.LootRow;
import com.sessionscribe.SessionScribePanel.SkillRow;
import com.sessionscribe.SessionScribePanel.Snapshot;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.List;
import javax.imageio.ImageIO;

/**
 * Renders a compact, screenshot-friendly end-of-session recap to a {@link BufferedImage}.
 * Pure drawing with no client or Swing dependencies, so it is unit-testable headlessly.
 * Top drops are drawn as text (name / quantity / value) rather than item icons, because item
 * images load asynchronously and would not be guaranteed present at render time.
 */
final class SessionReportCard
{
	private static final int WIDTH = 340;
	private static final int PAD = 16;
	private static final int TITLE_H = 30;
	private static final int LINE = 22;
	private static final int SMALL = 19;
	private static final int HEADER_H = 24;
	private static final int GAP = 12;
	private static final int MAX_SKILLS = 5;
	private static final int MAX_DROPS = 6;

	private static final Color BG = new Color(33, 33, 33);
	private static final Color BORDER = new Color(235, 140, 20);
	private static final Color TITLE = new Color(235, 140, 20);
	private static final Color TEXT = new Color(220, 220, 220);
	private static final Color MUTED = new Color(150, 150, 150);
	private static final Color VALUE = new Color(255, 255, 255);

	private static final Font TITLE_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 20);
	private static final Font DATE_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
	private static final Font HEADER_FONT = new Font(Font.SANS_SERIF, Font.BOLD, 13);
	private static final Font BODY_FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 13);

	private static final DateTimeFormatter DATE_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
	private static final DateTimeFormatter FILE_FMT = DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	private SessionReportCard()
	{
	}

	static BufferedImage render(Snapshot snapshot, boolean rounded, String subtitle)
	{
		final List<SkillRow> skills = snapshot.skillRows();
		final List<LootRow> drops = snapshot.lootRows();
		final int skillRows = Math.max(1, Math.min(MAX_SKILLS, skills.size()));
		final int dropRows = Math.max(1, Math.min(MAX_DROPS, drops.size()));

		final int height = PAD
			+ TITLE_H
			+ SMALL              // date
			+ SMALL              // subtitle
			+ SMALL              // duration
			+ GAP                // divider
			+ 3 * LINE           // xp / loot / kills
			+ GAP
			+ HEADER_H + skillRows * SMALL
			+ GAP
			+ HEADER_H + dropRows * SMALL
			+ PAD;

		final BufferedImage image = new BufferedImage(WIDTH, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		g.setColor(BG);
		g.fillRoundRect(0, 0, WIDTH - 1, height - 1, 14, 14);
		g.setColor(BORDER);
		g.drawRoundRect(0, 0, WIDTH - 1, height - 1, 14, 14);

		final int right = WIDTH - PAD;
		int y = PAD;

		y = left(g, "Session Scribe", PAD, y, TITLE_FONT, TITLE, TITLE_H);
		y = left(g, DATE_FMT.format(LocalDateTime.now()), PAD, y, DATE_FONT, MUTED, SMALL);
		y = left(g, subtitle, PAD, y, DATE_FONT, MUTED, SMALL);
		y = leftRight(g, "Session time", formatDuration(snapshot.elapsedMillis()), PAD, right, y, DATE_FONT, MUTED, TEXT, SMALL);

		g.setColor(MUTED);
		g.drawLine(PAD, y + GAP / 2, right, y + GAP / 2);
		y += GAP;

		y = leftRight(g, "Total XP gained", Values.format(snapshot.totalXp(), rounded), PAD, right, y, BODY_FONT, TEXT, VALUE, LINE);
		y = leftRight(g, "Total loot value", Values.format(snapshot.totalLootValue(), rounded) + " gp", PAD, right, y, BODY_FONT, TEXT, VALUE, LINE);
		y = leftRight(g, "Kills", Integer.toString(snapshot.kills()), PAD, right, y, BODY_FONT, TEXT, VALUE, LINE);
		y += GAP;

		y = left(g, "Top skills", PAD, y, HEADER_FONT, TITLE, HEADER_H);
		if (skills.isEmpty())
		{
			y = left(g, "No XP gained", PAD, y, BODY_FONT, MUTED, SMALL);
		}
		else
		{
			for (SkillRow row : skills.subList(0, Math.min(MAX_SKILLS, skills.size())))
			{
				y = leftRight(g, formatSkillName(row.skill()), "+" + Values.format(row.gainedXp(), rounded),
					PAD, right, y, BODY_FONT, TEXT, VALUE, SMALL);
			}
		}
		y += GAP;

		y = left(g, "Top drops", PAD, y, HEADER_FONT, TITLE, HEADER_H);
		if (drops.isEmpty())
		{
			left(g, "No loot received", PAD, y, BODY_FONT, MUTED, SMALL);
		}
		else
		{
			for (LootRow row : drops.subList(0, Math.min(MAX_DROPS, drops.size())))
			{
				final String name = row.quantity() > 1 ? row.name() + " x " + Values.count(row.quantity()) : row.name();
				y = leftRight(g, name, Values.format(row.value(), rounded) + " gp",
					PAD, right, y, BODY_FONT, TEXT, VALUE, SMALL);
			}
		}

		g.dispose();
		return image;
	}

	/** Writes the report as a PNG into {@code dir} (created if needed) and returns the file. */
	static File saveTo(BufferedImage image, File dir) throws IOException
	{
		if (!dir.exists() && !dir.mkdirs())
		{
			throw new IOException("Unable to create directory: " + dir);
		}
		final File out = new File(dir, "session-" + FILE_FMT.format(LocalDateTime.now()) + ".png");
		ImageIO.write(image, "png", out);
		return out;
	}

	private static int left(Graphics2D g, String text, int x, int y, Font font, Color color, int lineHeight)
	{
		g.setFont(font);
		g.setColor(color);
		final FontMetrics fm = g.getFontMetrics();
		g.drawString(text, x, y + fm.getAscent());
		return y + lineHeight;
	}

	private static int leftRight(Graphics2D g, String left, String right, int x, int rightEdge, int y,
		Font font, Color leftColor, Color rightColor, int lineHeight)
	{
		g.setFont(font);
		final FontMetrics fm = g.getFontMetrics();
		final int baseline = y + fm.getAscent();
		g.setColor(leftColor);
		g.drawString(left, x, baseline);
		g.setColor(rightColor);
		g.drawString(right, rightEdge - fm.stringWidth(right), baseline);
		return y + lineHeight;
	}

	private static String formatSkillName(net.runelite.api.Skill skill)
	{
		final String name = skill.name();
		return name.charAt(0) + name.substring(1).toLowerCase();
	}

	private static String formatDuration(long millis)
	{
		final long totalSeconds = millis / 1000;
		final long hours = totalSeconds / 3600;
		final long minutes = (totalSeconds % 3600) / 60;
		final long seconds = totalSeconds % 60;
		return hours > 0
			? String.format("%d:%02d:%02d", hours, minutes, seconds)
			: String.format("%d:%02d", minutes, seconds);
	}
}

package com.sessionscribe;

import java.awt.Image;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;

/** Minimal {@link Transferable} that places an image on the system clipboard. */
class ImageTransferable implements Transferable
{
	private final Image image;

	ImageTransferable(Image image)
	{
		this.image = image;
	}

	@Override
	public DataFlavor[] getTransferDataFlavors()
	{
		return new DataFlavor[]{DataFlavor.imageFlavor};
	}

	@Override
	public boolean isDataFlavorSupported(DataFlavor flavor)
	{
		return DataFlavor.imageFlavor.equals(flavor);
	}

	@Override
	public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
	{
		if (!DataFlavor.imageFlavor.equals(flavor))
		{
			throw new UnsupportedFlavorException(flavor);
		}
		return image;
	}
}

package com.sessionscribe;

import java.util.Map;
import net.runelite.api.Skill;

/** Immutable view for one (account, window) selection. lootTally is null when not itemized. */
final class Aggregate
{
	final long durationMs;
	final Map<Skill, Integer> xpBySkill;
	final long lootValue;
	final int kills;
	final Map<Integer, Integer> lootTally;

	Aggregate(long durationMs, Map<Skill, Integer> xpBySkill, long lootValue, int kills, Map<Integer, Integer> lootTally)
	{
		this.durationMs = durationMs;
		this.xpBySkill = xpBySkill;
		this.lootValue = lootValue;
		this.kills = kills;
		this.lootTally = lootTally;
	}

	long totalXp()
	{
		long total = 0;
		for (int gain : xpBySkill.values())
		{
			total += gain;
		}
		return total;
	}
}
